#include "document.h"
#include "project_import.h"
#include "project_encode.h"
#include <iostream>
#define CHECK(x) do{if(!(x))throw std::runtime_error(#x);}while(false)
int main(){try{using namespace moon;using namespace moon::project;Document d(2,2);ProjectBrushMetadata m{"old","Legacy","brushes/old.gray","brushes/old.rgba",65,1,-2,7};std::map<std::string,std::vector<std::uint8_t>> bytes{{m.dataFile,std::vector<std::uint8_t>(65,128)},{m.colorsFile,std::vector<std::uint8_t>(260,0)}};bytes[m.colorsFile][0]=10;bytes[m.colorsFile][3]=128;auto resource=decodeProjectBrushResource(m,bytes);d.setImportedProjectBrushes({resource});auto saved=encodeEditableProject(d);auto manifest=readProjectManifest(saved.bytes);CHECK(manifest.customBrushes.size()==1&&manifest.customBrushes[0].metadata.id=="old"&&manifest.customBrushes[0].brush.width==65&&manifest.customBrushes[0].brush.colors[0]==0x8000000a);auto a=prepareEditableImport(manifest);PaletteState palette;palette.entries.clear();palette.slots=a.palette.slots;palette.nextId=a.palette.nextId;for(auto& e:a.palette.entries)palette.entries.push_back({e.id,e.name,e.color});auto reopened=Document::fromImported(a.width,a.height,std::move(a.timeline),std::move(palette),a.id,a.name,a.sourceArchive);reopened.setImportedProjectBrushes(a.customBrushes);auto recovery=prepareEditableImport(readProjectManifest(encodeRecoveryProject(reopened).bytes));CHECK(recovery.customBrushes[0].brush.coverage==resource.brush.coverage);auto history=reopened.historySize();CHECK(reopened.deleteProjectBrush("old")&&reopened.dirty()&&reopened.historySize()==history);reopened.undo();CHECK(reopened.projectBrushes().empty());auto deleted=encodeEditableProject(reopened);CHECK(prepareEditableImport(readProjectManifest(deleted.bytes)).customBrushes.empty());Archive archive(deleted.bytes);CHECK(!archive.entries().count("brushes/old.gray"));std::cout<<"project brush roundtrip passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
